class Vec:
  def __init__(self, src=None) -> Self:
    if src is None:
        self.elements = []
    else:
        elements = list(src)
        for x in elements:
            if not isinstance(x, (int, float)):
                raise TypeError(f"Scalar must be a number: {type(x)}")
        self.elements = elements
